const items = $input.all();
const result = [];

for (const item of items) {
  let data = item.json.output ?? item.json;

  // Si data est une string JSON, on la parse
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      result.push({
        json: {
          error: `Erreur de parsing JSON: ${e.message}`,
          raw_output: data
        }
      });
      continue;
    }
  }

  const numero_bl = data.numero_bl ?? null;
  const lignes = data.lignes || [];

  for (const ligne of lignes) {
    result.push({
      json: {
        numero_bl: numero_bl,
        numero_bc: ligne.numero_bc ?? null,
        code_article: ligne.code_article ?? null,
        designation_ocr: ligne.designation_ocr ?? null,
        quantite: ligne.quantite ?? null
      }
    });
  }
}

return result;
